import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/http-api.md","filePath":"reference/http-api.md"}'),r={name:"reference/http-api.md"};function c(s,e,i,n,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p>Every route the orchestrator serves lives under <code>/api</code> on one Express app . The same HTTP server also carries the WebSocket stream, so the API origin and the live-data origin are always identical.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>The API is same-origin with the app: every path below is relative to your workspace URL, as <code>https://&lt;your-workspace-host&gt;/api/…</code>. Because the SPA, the API and the WebSocket share an origin, browser calls need no CORS handling and no second host.</p><h2 id="response-envelope" tabindex="-1">Response envelope <a class="header-anchor" href="#response-envelope" aria-label="Permalink to &quot;Response envelope&quot;">​</a></h2><p>Almost every JSON route returns an <code>ok</code> flag; failures carry a human <code>error</code> string. File-serving routes return bytes with a MIME type instead.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;No such run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>The terminal error handler maps body-parser failures to <code>400 Invalid JSON body</code> and <code>413 Payload too large</code>, and anything unexpected to <code>500 Internal error</code> — a stack is never returned.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Every request is authenticated. The stack mounts in this exact order:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it does</th></tr></thead><tbody><tr><td><code>/api/webhooks</code></td><td>Public ingress, mounted first with its own limiter</td></tr><tr><td>shared limiter</td><td>600 requests/min per IP across <code>/api</code></td></tr><tr><td><code>/api/health</code></td><td>Always reachable, even while Mongo is down</td></tr><tr><td><code>/api/bootstrap</code></td><td>Public; the handshake the client boots from</td></tr><tr><td><code>csrfOriginCheck</code></td><td>Origin check for the cookie-authenticated API</td></tr><tr><td><code>/api/auth</code></td><td>Public login/signup/reset/OAuth surface</td></tr><tr><td><code>requireSession</code></td><td>401 without a valid <code>saidi_session</code> cookie</td></tr><tr><td>org-less routes</td><td><code>/api/orgs</code>, <code>/api/invites</code>, <code>/api/admin</code></td></tr><tr><td><code>orgContext</code></td><td>Reads the <code>X-Saidi-Org</code> header, verifies membership, enters the tenant scope. Missing header → <code>400</code></td></tr><tr><td>permission gates</td><td>Per-router write gates (below)</td></tr><tr><td>org-scoped routers</td><td>Runs, chats, memory, crons, reflexes, …</td></tr></tbody></table><p>Credential endpoints get a second, much stricter limiter in front of the shared bucket: 10 requests/min keyed on IP + the submitted email, covering <code>/api/auth/login</code>, <code>/api/auth/forgot-password</code>, <code>/api/auth/reset-password</code>, <code>/api/auth/verify-email</code>, and the OAuth callback.</p><h3 id="permission-gates" tabindex="-1">Permission gates <a class="header-anchor" href="#permission-gates" aria-label="Permalink to &quot;Permission gates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prefix</th><th>Gate</th></tr></thead><tbody><tr><td><code>/api/settings</code>, <code>/api/secrets</code>, <code>/api/telegram</code>, <code>/api/import</code>, <code>/api/onboarding</code></td><td>Platform superadmin only (reads included)</td></tr><tr><td><code>/api/providers</code></td><td>Reads open; writes require superadmin</td></tr><tr><td><code>/api/crons</code></td><td>Writes require <code>crons.manage</code></td></tr><tr><td><code>/api/reflexes</code></td><td>Writes require <code>reflexes.manage</code></td></tr><tr><td><code>/api/memory</code></td><td>Writes require <code>memory.manage</code></td></tr><tr><td><code>/api/admin/*</code></td><td>Platform superadmin</td></tr></tbody></table><p>Runs, run files, run git views, and run assets share one ACL (<code>http/routes/run-acl.ts</code>): you may <strong>view</strong> a run you own, a run shared to you, or any run if you hold <code>runs.viewAll</code>; you may <strong>steer</strong> a run you own or any run if you hold <code>runs.steerAll</code>. A refused request returns <code>403</code> with <code>&quot;You do not have access to this run.&quot;</code> Chats apply the same shape with <code>chats.viewAll</code>.</p><p>MongoDB is the sole structured store. While it is disconnected, every <code>/api</code> route except <code>/api/health</code> returns <code>503 { ok: false, error: &quot;MongoDB unavailable&quot; }</code>.</p><h2 id="health-bootstrap" tabindex="-1">Health &amp; bootstrap <a class="header-anchor" href="#health-bootstrap" aria-label="Permalink to &quot;Health &amp; bootstrap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/health</code></td><td><code>{ ok, mongo }</code>. <code>200</code> when Mongo is connected, <code>503</code> otherwise</td></tr><tr><td><code>GET</code></td><td><code>/api/bootstrap</code></td><td>Local: <code>{ ok, mode: &#39;local&#39; }</code>. Cloud: <code>{ ok, mode: &#39;cloud&#39;, providers, user?, orgs? }</code>. A session that cannot be resolved returns <code>503</code> (retry) rather than pretending you are logged out</td></tr></tbody></table><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/state</code></td><td>The full dashboard snapshot — rosters, memory, runs, chats. Scoped to the requesting member in cloud mode; fails closed with <code>401</code> if the tenant locals are incomplete</td></tr><tr><td><code>POST</code></td><td><code>/api/state/reload</code></td><td>Re-hydrates the in-memory stores from MongoDB, then returns the fresh snapshot. The only runtime path that re-reads Mongo; it also nudges other dashboards to re-pull</td></tr></tbody></table><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><p>See <a href="/docs/reference/run-object">The Run Object</a> for the shape of what these return.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/runs</code></td><td><code>{ ok, runs }</code> — summaries, filtered to what you may view</td></tr><tr><td><code>GET</code></td><td><code>/api/runs/search?q=</code></td><td>Full-text search over title/brief/thread → <code>{ id, snippet }[]</code></td></tr><tr><td><code>POST</code></td><td><code>/api/runs</code></td><td>Create and start a run</td></tr><tr><td><code>GET</code></td><td><code>/api/runs/:id</code></td><td>One run, thread included</td></tr><tr><td><code>PATCH</code></td><td><code>/api/runs/:id/config</code></td><td>Run-wide execution overrides</td></tr><tr><td><code>PATCH</code></td><td><code>/api/runs/:id/agent-config</code></td><td>One actor&#39;s overrides</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/rename</code></td><td><code>{ title }</code>, trimmed to 140 chars</td></tr><tr><td><code>PUT</code></td><td><code>/api/runs/:id/share</code></td><td><code>{ userIds: string[] }</code> — replaces the viewer list</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/message</code></td><td><code>{ text, attachments? }</code> — send into the thread</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/attach-assets</code></td><td><code>{ files?, includeAlreadyAttached?, note? }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/upload?name=</code></td><td>Raw bytes, one file, 25 MB cap → <code>{ ok, file }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/control</code></td><td><code>{ action }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/rewind</code></td><td><code>{ eventId, text }</code> — edit and resend your last message</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/approval</code></td><td><code>{ approve: boolean, note? }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/plan-approval</code></td><td><code>{ approve: boolean, note? }</code> — sign off on the plan itself</td></tr><tr><td><code>DELETE</code></td><td><code>/api/runs/:id</code></td><td>Deletes the record and its assets; <code>?files=0</code> keeps the on-disk folder</td></tr></tbody></table><p><code>POST /api/runs</code> body:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>brief</code></td><td><code>string</code></td><td><strong>Required.</strong> Empty → <code>400</code></td></tr><tr><td><code>project?</code></td><td><code>string</code></td><td>Must resolve against the registry (case-insensitive) or <code>404</code></td></tr><tr><td><code>effort?</code></td><td><code>&#39;low&#39; | &#39;medium&#39; | &#39;high&#39;</code></td><td>Omitted/invalid falls back to the Settings default</td></tr><tr><td><code>provider?</code> / <code>model?</code></td><td><code>string</code></td><td>Run-wide overrides</td></tr><tr><td><code>executionMode?</code></td><td><code>&#39;guided&#39; | &#39;autonomous&#39;</code></td><td>Anything else keeps the Settings default</td></tr><tr><td><code>playbookId?</code></td><td><code>string</code></td><td>Explicit playbook wins; otherwise a saved plan for this exact brief is reused</td></tr></tbody></table><p>A run that cannot start because of the credits hard stop or a cloud governance gate (budget, concurrency, suspension) returns <code>402</code> with the reason.</p><p><code>control</code> accepts <code>pause</code>, <code>resume</code>, <code>stop</code> (halts the current turn, run stays open), <code>done</code>, <code>cancel</code>, <code>reopen</code>. Anything else is a <code>400</code>.</p><p>The two <code>PATCH</code> config routes take <code>provider</code>, <code>model</code>, and <code>effort</code> — a string sets the value, <code>&#39;&#39;</code> clears it back to <em>inherit</em>, and an omitted key is left alone. <code>agent-config</code> additionally requires <code>actor</code> (<code>&#39;PRIME&#39;</code>, a project, or an agent name). Both apply to future turns only, never retroactively.</p><p>Approval returns <code>202</code> when the decision was claimed (it queues behind a still-finishing turn) and <code>404</code> when nothing was pending.</p><h3 id="code-view" tabindex="-1">Code view <a class="header-anchor" href="#code-view" aria-label="Permalink to &quot;Code view&quot;">​</a></h3><p>Every git route verifies the run actually <em>participates</em> in the named project, so a viewable run id can never be used to read an unrelated org repo.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Query</th><th>Returns</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/runs/:id/git</code></td><td>—</td><td>Per-project snapshot: branches, commits, files, PR</td></tr><tr><td><code>GET</code></td><td><code>/api/runs/:id/git/compare</code></td><td><code>project</code>, <code>base</code>, <code>head</code></td><td>Changed-file list between two refs</td></tr><tr><td><code>GET</code></td><td><code>/api/runs/:id/git/worktree</code></td><td><code>project</code></td><td>Uncommitted worktree changes</td></tr><tr><td><code>GET</code></td><td><code>/api/runs/:id/git/file</code></td><td><code>project</code>, <code>file</code>, <code>base</code>, <code>head</code>, <code>mode?</code></td><td>One file&#39;s source</td></tr><tr><td><code>GET</code></td><td><code>/api/runs/:id/git/diff</code></td><td><code>project</code>, <code>file</code>, <code>base</code>, <code>head</code>, <code>mode?</code></td><td>One file&#39;s unified diff</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/git/checkout</code></td><td>body <code>{ project, branch }</code></td><td>Switch the run&#39;s working branch</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/publish</code></td><td>body <code>{ project, branch? }</code></td><td>Push the branch and open a PR</td></tr></tbody></table><p><code>mode=worktree</code> makes <code>base</code> and <code>head</code> optional; otherwise both are required.</p><h3 id="run-files" tabindex="-1">Run files <a class="header-anchor" href="#run-files" aria-label="Permalink to &quot;Run files&quot;">​</a></h3><p>The on-disk folder of one run (<code>assets/</code>, <code>work/&lt;agent&gt;/</code>, and the <code>run.json</code> record). Paths are resolved and realpath-guarded inside the run directory, so neither <code>..</code> nor a symlink can escape. <code>run.json</code> is protected from both delete routes.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/runs/:id/files?path=</code></td><td>Directory listing with recursive sizes, or capped file content. Caps: 500 entries, 256 KB of returned text, 8 MB per file. Binary files report <code>binary: true</code></td></tr><tr><td><code>GET</code></td><td><code>/api/runs/:id/fs?path=</code></td><td>Raw bytes, MIME-typed — inline image view and downloads</td></tr><tr><td><code>DELETE</code></td><td><code>/api/runs/:id/files?path=</code></td><td>Delete one file or directory</td></tr><tr><td><code>DELETE</code></td><td><code>/api/runs/:id/files/all</code></td><td>Clear everything except <code>run.json</code></td></tr></tbody></table><h3 id="playbooks" tabindex="-1">Playbooks <a class="header-anchor" href="#playbooks" aria-label="Permalink to &quot;Playbooks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/playbooks</code></td><td>Saved plans available for replay</td></tr><tr><td><code>POST</code></td><td><code>/api/runs/:id/playbook</code></td><td><code>{ name? }</code> — refuses an unfinished run</td></tr><tr><td><code>DELETE</code></td><td><code>/api/playbooks/:id</code></td><td>Remove a saved playbook</td></tr></tbody></table><h2 id="chats" tabindex="-1">Chats <a class="header-anchor" href="#chats" aria-label="Permalink to &quot;Chats&quot;">​</a></h2><p>Metadata and history only. Sending messages and streaming replies is the WebSocket&#39;s job. A chat&#39;s transcript is not stored on the chat record — it lives in the activity stream tagged with the chat id.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/chats</code></td><td>List (session id stripped)</td></tr><tr><td><code>POST</code></td><td><code>/api/chats</code></td><td><code>{ title? }</code> → the new chat</td></tr><tr><td><code>GET</code></td><td><code>/api/chats/:id</code></td><td><code>{ ok, chat, recent }</code> — up to 200 transcript rows, newest first, read durably from Mongo</td></tr><tr><td><code>PATCH</code></td><td><code>/api/chats/:id</code></td><td><code>{ title }</code> — owner or <code>chats.viewAll</code></td></tr><tr><td><code>PUT</code></td><td><code>/api/chats/:id/share</code></td><td><code>{ userIds: string[] }</code></td></tr><tr><td><code>DELETE</code></td><td><code>/api/chats/:id</code></td><td>Deletes the chat and wipes its transcript</td></tr></tbody></table><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/memory?file=&lt;relpath&gt;</code></td><td><code>{ ok, file, content }</code>. Bad path → <code>400</code>, missing → <code>404</code></td></tr><tr><td><code>POST</code></td><td><code>/api/memory</code></td><td><code>{ file, content }</code>, 1 MB limit, path-traversal guarded</td></tr></tbody></table><h2 id="crons" tabindex="-1">Crons <a class="header-anchor" href="#crons" aria-label="Permalink to &quot;Crons&quot;">​</a></h2><p>Clock-triggered scheduled work. Create/update validation is shared with PRIME&#39;s tools (see <a href="/docs/reference/orchestrator-tools">Orchestrator Tools</a>).</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/crons</code></td><td>List</td></tr><tr><td><code>POST</code></td><td><code>/api/crons</code></td><td><code>{ name, schedule, brief, project?, enabled? }</code></td></tr><tr><td><code>PATCH</code></td><td><code>/api/crons/:id</code></td><td>Any of the same fields</td></tr><tr><td><code>DELETE</code></td><td><code>/api/crons/:id</code></td><td></td></tr><tr><td><code>POST</code></td><td><code>/api/crons/:id/run</code></td><td>Fire now → <code>{ ok, runId }</code>. <code>409</code> if the previous run is still live</td></tr></tbody></table><h2 id="reflexes" tabindex="-1">Reflexes <a class="header-anchor" href="#reflexes" aria-label="Permalink to &quot;Reflexes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/reflexes</code></td><td>List</td></tr><tr><td><code>POST</code></td><td><code>/api/reflexes</code></td><td>Create</td></tr><tr><td><code>PATCH</code></td><td><code>/api/reflexes/:id</code></td><td>Update any field</td></tr><tr><td><code>DELETE</code></td><td><code>/api/reflexes/:id</code></td><td></td></tr><tr><td><code>POST</code></td><td><code>/api/reflexes/:id/test</code></td><td><code>{ payload, type? }</code> — fires the action directly. <code>409</code> if the sample payload doesn&#39;t satisfy the match tree</td></tr><tr><td><code>GET</code></td><td><code>/api/reflexes/log</code></td><td><code>{ events, fires }</code> — 150 of each</td></tr><tr><td><code>GET</code></td><td><code>/api/reflexes/pending</code></td><td>Fires parked for approval</td></tr><tr><td><code>POST</code></td><td><code>/api/reflexes/pending/:id/approve</code></td><td></td></tr><tr><td><code>POST</code></td><td><code>/api/reflexes/pending/:id/deny</code></td><td></td></tr></tbody></table><p>A manual test bypasses cooldown and approval and does <strong>not</strong> count toward <code>maxFires</code>, but it still writes to the console log.</p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>The only internet-facing surface, mounted at <code>/api/webhooks</code> with its own 300/min limiter ahead of the shared bucket. The raw body is kept for signature verification.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/webhooks/:source</code></td><td>Subscribe handshake — echoes <code>hub.challenge</code> when <code>hub.mode=subscribe</code> and <code>hub.verify_token</code> matches. Otherwise <code>403</code></td></tr><tr><td><code>POST</code></td><td><code>/api/webhooks/:source</code></td><td>Verify → normalize → push onto the bus → <code>{ ok, id, type, source }</code></td></tr></tbody></table><p>Built-in sources and their credentials:</p><table tabindex="0"><thead><tr><th>Source</th><th>Verification</th><th>Secret</th></tr></thead><tbody><tr><td><code>generic</code></td><td>Bearer token in <code>Authorization</code> or <code>X-Webhook-Token</code></td><td><code>SAIDI_WEBHOOK_GENERIC_TOKEN</code></td></tr><tr><td><code>github</code></td><td>HMAC-SHA256, <code>X-Hub-Signature-256</code>, <code>sha256=</code> hex</td><td><code>SAIDI_WEBHOOK_GITHUB_SECRET</code></td></tr><tr><td><code>stripe</code></td><td>HMAC over <code>\${t}.\${body}</code>, <code>Stripe-Signature</code> v1, ±300 s replay window</td><td><code>SAIDI_WEBHOOK_STRIPE_SECRET</code></td></tr><tr><td><code>whatsapp</code>, <code>instagram</code>, <code>messenger</code>, <code>meta</code></td><td>HMAC-SHA256, <code>X-Hub-Signature-256</code></td><td><code>SAIDI_WEBHOOK_META_SECRET</code></td></tr></tbody></table><p>Any other name falls through to the env-configured path — no code needed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SAIDI_WEBHOOK_&lt;NAME&gt;_SCHEME    bearer | hmac | none   (default: bearer if a secret is set)</span></span>
<span class="line"><span>SAIDI_WEBHOOK_&lt;NAME&gt;_SECRET    shared token or HMAC secret</span></span>
<span class="line"><span>SAIDI_WEBHOOK_&lt;NAME&gt;_HEADER    signature header       (hmac; default x-signature)</span></span>
<span class="line"><span>SAIDI_WEBHOOK_&lt;NAME&gt;_PREFIX    signature prefix       (hmac; default &quot;sha256=&quot;, &quot;&quot; for none)</span></span>
<span class="line"><span>SAIDI_WEBHOOK_&lt;NAME&gt;_ENCODING  hex | base64           (hmac; default hex)</span></span>
<span class="line"><span>SAIDI_WEBHOOK_&lt;NAME&gt;_VERIFY_TOKEN  token for the GET challenge</span></span></code></pre></div><p>A source with no configured secret is rejected <code>401</code> unless it explicitly opts into <code>SCHEME=none</code>. The POST acks fast with <code>200</code> — matching and actions run asynchronously on the bus, so the provider never retries on a slow reflex.</p><h2 id="assets-uploads" tabindex="-1">Assets &amp; uploads <a class="header-anchor" href="#assets-uploads" aria-label="Permalink to &quot;Assets &amp; uploads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/run-asset?run=&amp;file=</code></td><td>Serve a file an agent produced inside a run. Gated by the run view ACL, sandboxed to that run&#39;s <code>assets/</code> dir, streamed with Range support</td></tr><tr><td><code>GET</code></td><td><code>/api/chat-asset?file=</code></td><td>Serve a main-chat upload from the org&#39;s <code>chat-uploads/</code> dir</td></tr><tr><td><code>POST</code></td><td><code>/api/chat/upload?name=</code></td><td>Raw bytes, 25 MB cap → <code>{ ok, file }</code>. The stored name carries 16 random bytes so filenames cannot be enumerated</td></tr></tbody></table><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Superadmin-only in cloud mode. Files stay the source of truth, so every edit is git-diffable.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/settings</code></td><td><code>{ agents, projects, system }</code></td></tr><tr><td><code>PUT</code></td><td><code>/api/settings/agents/:name</code></td><td>Patch <code>agents/&lt;name&gt;/AGENT.md</code>: <code>description</code>, <code>department</code>, <code>model</code>, <code>cwd</code>, <code>prompt</code>, <code>lead</code>, <code>profile</code>, <code>effort</code>, <code>permission</code> (<code>all | read-only | custom</code>), <code>tools[]</code>. An empty <code>prompt</code> is refused</td></tr><tr><td><code>DELETE</code></td><td><code>/api/settings/agents/:name</code></td><td>Remove the whole agent directory</td></tr><tr><td><code>DELETE</code></td><td><code>/api/settings/agents/:name/skills/:slug</code></td><td>Remove one skill</td></tr><tr><td><code>DELETE</code></td><td><code>/api/settings/agents/:name/mcp/:server</code></td><td>Remove one MCP server</td></tr><tr><td><code>PUT</code></td><td><code>/api/settings/projects/:name</code></td><td><code>{ branch: &#39;new&#39; | &#39;current&#39; | null, approval: &#39;confirm&#39; | &#39;auto&#39; | null }</code> — <code>null</code> removes the declaration so the project inherits the system default</td></tr><tr><td><code>PUT</code></td><td><code>/api/settings/system</code></td><td>Patch <code>config/settings.json</code> (<code>ownerName</code>, <code>primeModel</code>, <code>defaultBranchMode</code>, <code>defaultApproval</code>, <code>cronTickSeconds ≥ 5</code>, and the rest of the system knobs)</td></tr></tbody></table><p>Agent and project writes reload the live roster in-process and push a <code>state_dirty</code> nudge, so PRIME sees the change on its next turn without a restart.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/secrets</code></td><td>Masked view — <code>{ set, hint }</code> per credential, redacted Mongo URI. Raw secrets are never returned</td></tr><tr><td><code>PUT</code></td><td><code>/api/secrets</code></td><td>Patch: a non-empty string <strong>sets</strong>, <code>null</code> <strong>clears</strong>, empty/absent <strong>leaves unchanged</strong></td></tr></tbody></table><p>Managed fields: <code>mongodbUri</code>, <code>anthropicApiKey</code>, <code>anthropicAuthToken</code>, <code>claudeCodeOauthToken</code>, <code>anthropicModel</code>, <code>anthropicBaseUrl</code>, <code>openaiApiKey</code>, <code>saidiGithubToken</code>, <code>webhookGenericToken</code>, <code>webhookGithubSecret</code>, <code>webhookStripeSecret</code>, <code>webhookMetaSecret</code>, <code>webhookMetaVerifyToken</code>. Values are validated before they are persisted, then applied to <code>process.env</code> live where possible.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/providers</code></td><td><code>{ profiles, defaultId }</code> with tokens masked</td></tr><tr><td><code>POST</code></td><td><code>/api/providers</code></td><td>Create or update a custom profile — <code>id</code>, <code>name</code>, and per-effort <code>tiers</code> (<code>low</code>/<code>medium</code>/<code>high</code>, each its own <code>model</code>, <code>baseUrl</code>, <code>authToken</code>, <code>priceIn</code>, <code>priceOut</code>)</td></tr><tr><td><code>POST</code></td><td><code>/api/providers/test</code></td><td>Live probe of <code>{ model, baseUrl?, authToken?, profileId?, effort? }</code>. Posts a 16-token <code>ping</code> to <code>&lt;baseUrl&gt;/v1/messages</code> with a 20 s timeout and reports status + latency</td></tr><tr><td><code>DELETE</code></td><td><code>/api/providers/:id</code></td><td>Delete a custom profile; the built-ins refuse</td></tr></tbody></table><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>Four package kinds — <code>agent</code>, <code>department</code>, <code>skill</code>, <code>mcp</code>. Installing or removing each kind is gated by its own org permission (<code>market.install.&lt;kind&gt;</code>).</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/marketplace/config</code></td><td><code>{ registryUrl, installed }</code></td></tr><tr><td><code>PUT</code></td><td><code>/api/marketplace/config</code></td><td><code>{ registryUrl }</code> — superadmin</td></tr><tr><td><code>GET</code></td><td><code>/api/marketplace/sources</code></td><td>Available browse sources</td></tr><tr><td><code>PUT</code></td><td><code>/api/marketplace/sources/skillsmp-key</code></td><td><code>{ key }</code> — superadmin</td></tr><tr><td><code>GET</code></td><td><code>/api/marketplace/packages?q=&amp;kind=&amp;registryUrl=</code></td><td>Catalog search. Only a superadmin may override <code>registryUrl</code> (the SSRF surface)</td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/preview</code></td><td><code>{ packageUrl }</code> — validate and describe before installing</td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/install</code></td><td><code>{ packageUrl, overwrite?, targetAgent?, createAgent? }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/update</code></td><td><code>{ id }</code> — reinstall at latest, reusing the recorded target</td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/uninstall</code></td><td><code>{ id }</code> → <code>{ ok, removed }</code></td></tr><tr><td><code>GET</code></td><td><code>/api/marketplace/versions?id=</code> · <code>/reviews?id=</code></td><td>Proxied to the hosted API</td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/reviews</code> · <code>/report</code></td><td><code>{ id, rating, text }</code> · <code>{ id, reason, version? }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/auth/start</code> · <code>/auth/poll</code></td><td>GitHub device flow; the device code and GitHub access token stay server-side</td></tr><tr><td><code>GET</code></td><td><code>/api/marketplace/account</code> · <code>POST /signout</code></td><td>Publisher identity</td></tr><tr><td><code>POST</code></td><td><code>/api/marketplace/publish</code> · <code>/unpublish</code></td><td>Publish to the hosted API or a GitHub repo via <code>gh</code></td></tr></tbody></table><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Additive/merge only — import never deletes anything in the target.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Body</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/import/agents/preview</code></td><td><code>{ sourceDir }</code> → detected agent folders with an <code>exists</code> flag</td></tr><tr><td><code>POST</code></td><td><code>/api/import/agents</code></td><td><code>{ sourceDir, overwrite?, names? }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/import/memory/preview</code></td><td><code>{ sourceDir }</code> → detected memory items</td></tr><tr><td><code>POST</code></td><td><code>/api/import/memory</code></td><td><code>{ sourceDir, overwrite?, includeSecrets?, includeRuns? }</code></td></tr></tbody></table><p>An agent folder that already exists is skipped unless <code>overwrite: true</code>. Secret files and run history are excluded unless you opt in, so an import cannot silently clobber the install&#39;s credentials.</p><h2 id="browse-entities" tabindex="-1">Browse &amp; entities <a class="header-anchor" href="#browse-entities" aria-label="Permalink to &quot;Browse &amp; entities&quot;">​</a></h2><p>Strictly read-only. An agent&#39;s root is its <code>agents/&lt;name&gt;/</code> directory; a project&#39;s root is its registered repo path. Every request path is resolved and guarded inside that root, symlinks included.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/entity?kind=agent|project&amp;name=</code></td><td>Profile, skills, MCP servers, policy, and the memory file&#39;s relpath + existence</td></tr><tr><td><code>GET</code></td><td><code>/api/browse?kind=&amp;name=&amp;path=</code></td><td>Directory listing or capped text content — same 500-entry / 256 KB / 8 MB caps as the run browser</td></tr></tbody></table><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><code>GET /api/entity/mcp?name=</code> live-probes one agent&#39;s MCP servers and returns status, tools, and a <code>needsAuth</code> flag. <code>POST /api/entity/mcp/auth</code> with <code>{ name, server }</code> begins OAuth and returns an <code>authUrl</code> to open; <code>GET /api/mcp/oauth/callback</code> is the redirect target that stores the tokens.</p><h2 id="realtime-voice" tabindex="-1">Realtime &amp; voice <a class="header-anchor" href="#realtime-voice" aria-label="Permalink to &quot;Realtime &amp; voice&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/realtime/config</code></td><td><code>{ textProvider, realtimeModel }</code> — deliberately narrower than the full Settings snapshot</td></tr><tr><td><code>POST</code></td><td><code>/api/realtime/session</code></td><td>Body is the browser&#39;s SDP offer (<code>application/sdp</code>). Attaches PRIME&#39;s prompt and tools, authenticates upstream, and returns the SDP answer. <code>503</code> without <code>OPENAI_API_KEY</code>, <code>402</code> when credits block, <code>502</code> if the provider is unreachable</td></tr><tr><td><code>POST</code></td><td><code>/api/voice/metrics</code></td><td><code>{ turnId, committedAt, … , usage? }</code> — the audio leg is browser↔provider, so the turn reports its own token counts, which settle into the wallet</td></tr><tr><td><code>GET</code></td><td><code>/api/voice/metrics</code></td><td>The last 50 metrics</td></tr></tbody></table><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><p>Superadmin-only in cloud mode. The raw bot token is never returned; token changes are validated against Telegram&#39;s <code>getMe</code> before they are persisted and are applied to the live service without a restart.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/telegram</code></td><td><code>{ config (masked), status, accounts }</code></td></tr><tr><td><code>PUT</code></td><td><code>/api/telegram</code></td><td><code>{ enabled?, botToken?, allowedUserIds? }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/telegram/test</code></td><td>Validate a token without saving it</td></tr><tr><td><code>POST</code></td><td><code>/api/telegram/accounts/:id</code></td><td><code>{ authorized }</code> — allow or revoke one account</td></tr></tbody></table><h2 id="onboarding" tabindex="-1">Onboarding <a class="header-anchor" href="#onboarding" aria-label="Permalink to &quot;Onboarding&quot;">​</a></h2><p><code>GET /api/onboarding</code> returns the first-run doctor&#39;s non-secret readiness report; <code>POST /api/onboarding/setup</code> applies safe local auto-fixes and returns a fresh report. Superadmin-only in cloud mode.</p><h2 id="credits-cloud" tabindex="-1">Credits (cloud) <a class="header-anchor" href="#credits-cloud" aria-label="Permalink to &quot;Credits (cloud)&quot;">​</a></h2><p>Grants and revocations live exclusively on the superadmin plane; the org plane is read-only.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/credits</code></td><td><code>{ wallet, allowance }</code> — the balance <em>this member</em> may spend, after their monthly budget</td></tr><tr><td><code>GET</code></td><td><code>/api/credits/usage?limit=N</code></td><td><code>{ wallet, ledger, users }</code>. Requires <code>billing.view</code> or <code>usage.viewOrg</code>. <code>limit</code> is clamped to 1–500, default 250</td></tr></tbody></table><h2 id="auth" tabindex="-1">Auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;Auth&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Body</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/auth/signup</code></td><td><code>{ email, password, name }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/auth/login</code></td><td><code>{ email, password }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/auth/logout</code></td><td>—</td></tr><tr><td><code>GET</code></td><td><code>/api/auth/me</code></td><td>→ <code>{ user, orgs }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/auth/verify-email</code></td><td><code>{ token }</code></td></tr><tr><td><code>POST</code></td><td><code>/api/auth/resend-verification</code></td><td>Session required</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/forgot-password</code></td><td><code>{ email }</code> — always <code>200</code>, so the endpoint cannot enumerate accounts</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/reset-password</code></td><td><code>{ token, password }</code></td></tr><tr><td><code>GET</code></td><td><code>/api/auth/oauth/:provider</code></td><td><code>302</code> to the provider</td></tr><tr><td><code>GET</code></td><td><code>/api/auth/oauth/:provider/callback</code></td><td>Logs in or links, then <code>302</code> to <code>/</code></td></tr><tr><td><code>GET</code></td><td><code>/api/auth/providers</code></td><td>Which OAuth providers are configured</td></tr></tbody></table><p>Sessions ride an httpOnly <code>saidi_session</code> cookie with a 30-day max age. Logging out or resetting a password force-closes that user&#39;s live WebSockets.</p><h2 id="organizations-cloud" tabindex="-1">Organizations (cloud) <a class="header-anchor" href="#organizations-cloud" aria-label="Permalink to &quot;Organizations (cloud)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Gate</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/invites/preview?token=</code></td><td>Public — the recipient is logged out</td></tr><tr><td><code>POST</code></td><td><code>/api/orgs</code></td><td><code>{ name, seats }</code>; verified email required</td></tr><tr><td><code>GET</code></td><td><code>/api/orgs</code></td><td>Your orgs</td></tr><tr><td><code>POST</code></td><td><code>/api/invites/accept</code></td><td><code>{ token }</code></td></tr><tr><td><code>GET</code></td><td><code>/api/org</code></td><td>Org + seat usage</td></tr><tr><td><code>PATCH</code></td><td><code>/api/org</code></td><td><code>{ name?, settings? }</code> — <code>settings.manage</code></td></tr><tr><td><code>PATCH</code></td><td><code>/api/org/seats</code></td><td><code>{ seats }</code> — owner</td></tr><tr><td><code>GET</code></td><td><code>/api/org/members</code></td><td><code>members.manage</code></td></tr><tr><td><code>GET</code></td><td><code>/api/members</code></td><td>The roster every member may see</td></tr><tr><td><code>PATCH</code></td><td><code>/api/org/members/:userId</code></td><td><code>{ role?, limits?, permissionOverrides?, agentAccess? }</code> — <code>members.manage</code></td></tr><tr><td><code>DELETE</code></td><td><code>/api/org/members/:userId</code></td><td><code>members.manage</code></td></tr><tr><td><code>GET</code> <code>POST</code></td><td><code>/api/org/invites</code></td><td><code>members.manage</code></td></tr><tr><td><code>POST</code></td><td><code>/api/org/invites/:id/resend</code></td><td>Issues a fresh token; the old link dies</td></tr><tr><td><code>DELETE</code></td><td><code>/api/org/invites/:id</code></td><td><code>members.manage</code></td></tr></tbody></table><p>Changing a membership closes that member&#39;s live sockets so they re-handshake with the new governance rather than acting on cached permissions.</p><h2 id="admin-plane-cloud" tabindex="-1">Admin plane (cloud) <a class="header-anchor" href="#admin-plane-cloud" aria-label="Permalink to &quot;Admin plane (cloud)&quot;">​</a></h2><p>Every route sits behind <code>requireSuperadmin</code> and operates across orgs, outside any org context.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/admin/orgs</code></td><td>All orgs: seats, members, balance, burn, status</td></tr><tr><td><code>GET</code></td><td><code>/api/admin/orgs/:id</code></td><td>Drilldown: members, wallet, ledger, run counts</td></tr><tr><td><code>POST</code></td><td><code>/api/admin/orgs/:id/credits</code></td><td><code>{ amount, note? }</code> — negative revokes. The only credit mutation in the product</td></tr><tr><td><code>POST</code></td><td><code>/api/admin/orgs/:id/suspend</code> · <code>/reinstate</code></td><td>Suspending closes every socket in the org</td></tr><tr><td><code>PATCH</code></td><td><code>/api/admin/orgs/:id/limits</code></td><td><code>{ maxConcurrentRuns?, seats? }</code></td></tr><tr><td><code>GET</code></td><td><code>/api/admin/metrics</code></td><td>Platform totals</td></tr><tr><td><code>GET</code></td><td><code>/api/admin/users</code></td><td>Cross-org user list</td></tr></tbody></table><h2 id="body-size-limits" tabindex="-1">Body size limits <a class="header-anchor" href="#body-size-limits" aria-label="Permalink to &quot;Body size limits&quot;">​</a></h2><p>JSON bodies are capped per surface: 64 KB (chat, auth, org, admin), 256 KB (cron, reflex, secret, provider, Telegram, import), 1 MB (run, memory, settings, realtime SDP), 2 MB (marketplace). Raw uploads are capped at 25 MB, webhook bodies at 1 MB, voice metrics at 32 KB.</p><p>See also: <a href="/docs/concepts/runs">Runs</a> · <a href="/docs/reference/run-object">The Run Object</a> · <a href="/docs/concepts/reflexes-and-events">Reflexes &amp; Events</a></p>`,102)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
